/* Strict display override guard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1c23;
  --color-card: #272a37;
  --color-accent: #f2a900;
  --color-accent-light: #ffd166;
  --color-text: #f0f2f5;
  --color-muted: #9aa0a6;
  --color-border: #3d4255;
  --color-danger: #ef476f;
  --color-success: #06d6a0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.auction-container {
  width: 100%;
  max-width: 440px;
}

.auction-card {
  background-color: var(--color-card);
  border: 3px solid var(--color-border);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.auction-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
}

.badge {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: rgba(242, 169, 0, 0.15);
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(242, 169, 0, 0.3);
}

.auction-header h1 {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-text);
}

.pixel-art-frame {
  background-color: #121319;
  border: 2px dashed var(--color-border);
  border-radius: 8px;
  padding: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
}

#pixelCanvas {
  image-rendering: pixelated;
  width: 128px;
  height: 128px;
}

.auction-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.stat-box {
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 12px;
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.stat-value {
  display: block;
  font-size: 28px;
  font-weight: 800;
}

.price-text {
  color: var(--color-accent-light);
}

.timer-text {
  color: var(--color-text);
  transition: color 0.2s ease;
}

.timer-warning {
  color: var(--color-danger);
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  from { opacity: 1; transform: scale(1); }
  to { opacity: 0.85; transform: scale(1.05); }
}

.status-banner {
  background-color: var(--color-success);
  color: #0b241c;
  font-weight: 800;
  font-size: 20px;
  text-align: center;
  padding: 14px;
  border-radius: 8px;
  box-shadow: 0 4px 12px rgba(6, 214, 160, 0.3);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font-size: 18px;
  font-weight: 700;
  padding: 14px 16px;
  border: 2px solid var(--color-border);
  background: #333849;
  color: var(--color-text);
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
}

.btn:hover:not(:disabled) {
  background: #3e4458;
  border-color: #555c74;
}

.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translateY(2px);
}

.btn-primary {
  background-color: var(--color-accent);
  border-color: #d19200;
  color: #121319;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(0.6);
}

@media (max-width: 360px) {
  .auction-card {
    padding: 16px;
  }
  .stat-value {
    font-size: 24px;
  }
  .btn {
    font-size: 16px;
    padding: 12px 10px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let currentPrice = 10;
  let remainingTime = 45;
  let timerId = null;
  let isAuctionEnded = false;

  const priceDisplay = document.getElementById('priceDisplay');
  const timeDisplay = document.getElementById('timeDisplay');
  const statusBanner = document.getElementById('statusBanner');
  const bid1Btn = document.getElementById('bid1Btn');
  const bid5Btn = document.getElementById('bid5Btn');
  const canvas = document.getElementById('pixelCanvas');

  function drawPixelArt() {
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    const size = 6;
    const pixelMap = [
      '                ',
      '             bb ',
      '            baab',
      '           baab ',
      '          baab  ',
      '     c   baab   ',
      '    cbc baab    ',
      '   cbbcbaab     ',
      '  cbbbcabb      ',
      ' cbbbc baab     ',
      '  cbc   baab    ',
      '   c     baab   ',
      '          baab  ',
      '           dd   ',
      '            dd  ',
      '                '
    ];

    const colorPalette = {
      a: '#00e5ff',
      b: '#00838f',
      c: '#ffd166',
      d: '#8d6e63'
    };

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let r = 0; r < pixelMap.length; r++) {
      for (let c = 0; c < pixelMap[r].length; c++) {
        const char = pixelMap[r][c];
        if (colorPalette[char]) {
          ctx.fillStyle = colorPalette[char];
          ctx.fillRect(c * size, r * size, size, size);
        }
      }
    }
  }

  function updateUI() {
    priceDisplay.textContent = currentPrice;
    timeDisplay.textContent = `${remainingTime}s`;

    if (remainingTime <= 10 && !isAuctionEnded) {
      timeDisplay.classList.add('timer-warning');
    } else {
      timeDisplay.classList.remove('timer-warning');
    }
  }

  function endAuction() {
    isAuctionEnded = true;
    clearInterval(timerId);
    timerId = null;
    remainingTime = 0;
    timeDisplay.textContent = '0s';
    timeDisplay.classList.remove('timer-warning');

    bid1Btn.disabled = true;
    bid5Btn.disabled = true;

    statusBanner.textContent = `Sold for ${currentPrice}`;
    statusBanner.removeAttribute('hidden');
  }

  function tick() {
    if (remainingTime > 1) {
      remainingTime -= 1;
      updateUI();
    } else {
      endAuction();
    }
  }

  function placeBid(increment) {
    if (isAuctionEnded) return;

    currentPrice += increment;

    if (remainingTime < 10) {
      remainingTime = 10;
    }

    updateUI();
  }

  bid1Btn.addEventListener('click', () => placeBid(1));
  bid5Btn.addEventListener('click', () => placeBid(5));

  drawPixelArt();
  updateUI();
  timerId = setInterval(tick, 1000);
});
